from itertools import combinations
from typing import FrozenSet, List, Set, Tuple

Attack = Tuple[str, str]
ArgSet = FrozenSet[str]

def attackers(arg: str, attacks: Set[Attack]) -> Set[str]:
    return {b for (b, a) in attacks if a == arg}

def defends(s: ArgSet, arg: str, attacks: Set[Attack]) -> bool:
    return all(any((c, b) in attacks for c in s)
               for b in attackers(arg, attacks))

def char_F(s: ArgSet, universe: FrozenSet[str], attacks: Set[Attack]) -> ArgSet:
    return frozenset(a for a in universe if defends(s, a, attacks))

def is_conflict_free(s: ArgSet, attacks: Set[Attack]) -> bool:
    return not any((a, b) in attacks for a in s for b in s)

def is_complete(s: ArgSet, universe: FrozenSet[str], attacks: Set[Attack]) -> bool:
    return (is_conflict_free(s, attacks)
            and all(defends(s, a, attacks) for a in s)
            and char_F(s, universe, attacks) <= s)

def all_subsets(universe: FrozenSet[str]) -> List[ArgSet]:
    elems = sorted(universe)
    return [frozenset(c) for r in range(len(elems) + 1)
            for c in combinations(elems, r)]

