    return frozenset(a for a in universe if defends(a))

def family_meet(family: List[ArgSet], universe: FrozenSet[str],
                attacks: Set[Attack]) -> ArgSet:
    inter: ArgSet = universe if not family else family[0]
    for s in family[1:]:
        inter = inter & s
    elems = sorted(inter)
    result: Set[str] = set()
    for r in range(len(elems) + 1):
        for combo in combinations(elems, r):
            s = frozenset(combo)
            if s <= char_F(s, universe, attacks):
                result |= s
    return frozenset(result)

