    return not any((a, b) in attacks for a in s for b in s)

def defends(s: ArgSet, a: str, attacks: Set[Attack]) -> bool:
    return all(any((c, b) in attacks for c in s) for b in attackers(a, attacks))

def is_admissible(s: ArgSet, attacks: Set[Attack]) -> bool:
    return is_conflict_free(s, attacks) and all(defends(s, a, attacks) for a in s)

def preferred_extensions(universe: FrozenSet[str],
                         attacks: Set[Attack]) -> List[ArgSet]:
    elems = sorted(universe)
    subs = [frozenset(c) for r in range(len(elems) + 1)
            for c in combinations(elems, r)]
    adm = [s for s in subs if is_admissible(s, attacks)]
    return [s for s in adm if not any(s < t for t in adm)]

