import matplotlib.pyplot as plt

def char_F(s, universe, attacks):
    def att(a): return {b for (b, x) in attacks if x == a}
    def defends(a): return all(any((c, b) in attacks for c in s) for b in att(a))
    return frozenset(a for a in universe if defends(a))

